using System;
using System.IO;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
public static class B05SkinChecks
{
 static void Attach(GameObject go,Sprite sprite){var source=go.GetComponent<SpriteRenderer>();var child=new GameObject("V2 visual");child.transform.SetParent(go.transform,false);var image=child.AddComponent<SpriteRenderer>();image.sprite=sprite;image.sortingOrder=source.sortingOrder;var skin=go.AddComponent<V2Skin>();skin.source=source;skin.image=image;}
 public static void Input(){SessionState.SetString("N1.Suffix","B05-V2");N1Verification.Input();SkinFixture();}
 public static void Buffer(){SessionState.SetString("N1.Suffix","B05-V2");N1Verification.Forgiveness();SkinFixture();}
 static void SkinFixture(){var p=UnityEngine.Object.FindFirstObjectByType<PlayerInputReader>();Attach(p.gameObject,AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/V2/Player_V2.prefab").GetComponentInChildren<V2Skin>().image.sprite);}
 public static void Assets(){string output="";foreach(string id in new[]{"Landing","Wall","Ceiling","Door","KillZone","PogoTarget","Player","E1","E2","E3"}){string original="Assets/Prefabs/"+(id is "Landing" or "Wall" or "Ceiling" or "Door" or "KillZone"?"Level/":"")+id+".prefab";var a=AssetDatabase.LoadAssetAtPath<GameObject>(original);var b=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/V2/"+id+"_V2.prefab");var ac=a.GetComponentsInChildren<BoxCollider2D>(true);var bc=b.GetComponentsInChildren<BoxCollider2D>(true);bool same=ac.Length==bc.Length;for(int n=0;n<ac.Length&&same;n++)same=ac[n].size==bc[n].size&&ac[n].offset==bc[n].offset&&ac[n].isTrigger==bc[n].isTrigger&&ac[n].transform.localPosition==bc[n].transform.localPosition&&ac[n].transform.localScale==bc[n].transform.localScale;output+=(same?"PASS":"FAIL")+" collider diff0 "+id+" type="+PrefabUtility.GetPrefabAssetType(b)+"\n";}
  EditorSceneManager.OpenScene("Assets/Scenes/C06.unity");var boss=UnityEngine.Object.FindFirstObjectByType<BossEncounter>();var clone=UnityEngine.Object.Instantiate(boss.gameObject);clone.name="V2 Boss base from unchanged C06";var cb=clone.GetComponent<BossEncounter>();var warning=UnityEngine.Object.Instantiate(boss.warning.gameObject,clone.transform);cb.warning=warning.GetComponent<SpriteRenderer>();cb.leftExit=null;var baseBoss=PrefabUtility.SaveAsPrefabAsset(clone,"Assets/Prefabs/V2/BossBase_V2.prefab");UnityEngine.Object.DestroyImmediate(clone);var variant=(GameObject)PrefabUtility.InstantiatePrefab(baseBoss);Attach(variant,AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/V2/E3_V2.prefab").GetComponentInChildren<V2Skin>().image.sprite);PrefabUtility.SaveAsPrefabAsset(variant,"Assets/Prefabs/V2/Boss_V2.prefab");UnityEngine.Object.DestroyImmediate(variant);output+="PASS Boss extracted unchanged C06 collider; V2 variant; leftExit must bind in candidate Scene\n";
  EditorSceneManager.OpenScene("Assets/Scenes/V2/A01_V2.unity");var room=UnityEngine.Object.FindFirstObjectByType<RoomDefinition>();for(int n=1;n<=3;n++){var go=new GameObject("V2 E"+n+" skin test reset");go.transform.SetParent(room.transform);go.transform.position=new Vector2(20+n*8,1.6f);go.AddComponent<EnemyReset>().prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/V2/E"+n+"_V2.prefab");}EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/Scenes/V2/SkinTest_V2.unity");File.WriteAllText("Validation/_raw/B05/skin-collider-check.txt",output);AssetDatabase.SaveAssets();EditorApplication.Exit(output.Contains("FAIL")?1:0);
 }
}
